    '{\n  "apiVersion": "opensesame.dev/v1alpha1",\n  "kind": "VaultItemType",\n  "metadata": {\n    "id": "ssh-key",\n    "version": "1.0.0",\n    "publisher": "https://opensesame.dev"\n  },\n  "spec": {\n    "title": "SSH key",\n    "plural": "SSH keys",\n    "extension": ".ssh",\n    "summary": "An SSH key pair, its fingerprint, and the hosts it opens.",\n    "categories": ["access", "developer"],\n    "sections": [\n      {\n        "id": "key",\n        "title": "Key",\n        "fields": [\n          {\n            "id": "keyType",\n            "type": "select",\n            "label": "Key type",\n            "options": ["ed25519", "ecdsa", "rsa", "ed25519-sk", "ecdsa-sk"]\n          },\n          { "id": "keyPair", "type": "key-pair", "label": "Key pair" },\n          { "id": "passphrase", "type": "password", "label": "Passphrase" },\n          { "id": "fingerprint", "type": "string", "label": "Fingerprint" },\n          { "id": "comment", "type": "string", "label": "Comment" }\n        ]\n      },\n      {\n        "id": "use",\n        "title": "Where it is used",\n        "fields": [\n          { "id": "hosts", "type": "host-port", "label": "Host" },\n          { "id": "principal", "type": "string", "label": "Remote user" }\n        ]\n      }\n    ],\n    "native": {\n      "secret": "passphrase",\n      "trailer": [\n        { "key": "key_type", "field": "keyType" },\n        { "key": "key", "field": "keyPair" },\n        { "key": "fingerprint", "field": "fingerprint" },\n        { "key": "comment", "field": "comment" },\n        { "key": "host", "field": "hosts" },\n        { "key": "login", "field": "principal" }\n      ]\n    },\n    "cxf": { "credential": "ssh-key" },\n    "subtitle": ["keyType", "comment"],\n    "search": ["keyType", "comment", "fingerprint", "principal"]\n  }\n}',
